"""Shared engine contracts. All paths are generated by the local API, never by remote clients."""
from pathlib import Path
import json, re, unicodedata
import pymupdf as fitz

class UserError(Exception):
    pass

def safe_name(name, fallback='document'):
    name = unicodedata.normalize('NFKC', str(name or fallback))
    name = re.sub(r'[\\/\x00-\x1f]', '_', name).strip('. ')
    return (name[:150] or fallback)

def parse_pages(spec, count, default_all=True):
    if spec in (None, '', 'all'):
        return list(range(count)) if default_all else []
    result=[]
    for part in str(spec).split(','):
        part=part.strip().lower()
        if not part: continue
        if part in ('odd','even'):
            result.extend(i for i in range(count) if (i+1)%2 == (1 if part=='odd' else 0))
            continue
        m=re.fullmatch(r'(\d+)(?:\s*-\s*(\d+))?',part)
        if not m: raise UserError(f'Invalid page range: {part}. Use pages such as 1-3, 5, 8.')
        a=int(m[1]); b=int(m[2] or a)
        if a<1 or b<a or b>count: raise UserError(f'Page range {part} is outside this document ({count} pages).')
        result.extend(range(a-1,b))
    if len(set(result))!=len(result): raise UserError('A page may only appear once in this selection. Use Duplicate pages to make copies.')
    return result

def color(value, default=(0,0,0)):
    try:
        s=str(value or '').lstrip('#')
        if len(s)==3: s=''.join(x*2 for x in s)
        if len(s)!=6: return default
        return tuple(int(s[i:i+2],16)/255 for i in (0,2,4))
    except Exception: return default

def open_pdf(file, password=None):
    doc=fitz.open(file['path'])
    if doc.needs_pass and not doc.authenticate(str(password or '')):
        doc.close()
        raise UserError('This PDF is encrypted. Enter the correct password to continue.')
    if doc.page_count>1500:
        doc.close(); raise UserError('This personal edition accepts up to 1,500 pages per PDF. Split the document first.')
    return doc

def page_size(options):
    sizes={'a4':(595.28,841.89),'a3':(841.89,1190.55),'letter':(612,792),'legal':(612,1008),'a5':(419.53,595.28)}
    w,h=sizes.get(str(options.get('pageSize','a4')).lower(), sizes['a4'])
    if options.get('pageSize')=='custom':
        w=float(options.get('width',210))*72/25.4
        h=float(options.get('height',297))*72/25.4
    if not (72<=w<=2880 and 72<=h<=2880): raise UserError('Custom page dimensions must be between 25.4 and 1,016 mm.')
    return (h,w) if options.get('orientation')=='landscape' else (w,h)

def output(ctx, path, name=None, **meta):
    p=Path(path)
    if not p.exists() or not p.stat().st_size: raise UserError(f'The engine did not produce a valid file: {p.name}')
    item={'path':str(p),'name':safe_name(name or p.name),'size':p.stat().st_size,**meta}
    ctx['results'].append(item)
    return item

def save(ctx, doc, stem, suffix='', **meta):
    p=Path(ctx['out']) / (safe_name(stem)+suffix+'.pdf')
    doc.save(str(p),garbage=4,deflate=True)
    return output(ctx,p,**meta)

def progress(ctx, message, percent=None):
    data={'message':message}
    if percent is not None: data['percent']=max(0,min(100,round(percent)))
    Path(ctx['progress']).write_text(json.dumps(data))

def note(ctx, message):
    ctx.setdefault('notes',[]).append(message)

def unicode_font():
    p=Path('/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf')
    return p if p.exists() else Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')

def insert_unicode(page,rect,text,size=12,color_value=(0,0,0),fontfile=None):
    # MuPDF HTML shaping currently lacks a reliable Devanagari Unicode map.
    # Render a tightly sized text PDF with Chromium, then embed its vector content.
    import subprocess, html, tempfile
    if not str(text):return 1
    fp=Path(fontfile) if fontfile else unicode_font()
    css='body{margin:0;color:black;font-family:Studio,sans-serif;font-size:'+str(size)+'pt;line-height:1.25;white-space:pre-wrap;overflow-wrap:anywhere}'
    if fontfile:css='@font-face{font-family:Studio;src:url(data:font/ttf;base64,'+__import__('base64').b64encode(fp.read_bytes()).decode()+')}'+css
    opts={'html':'<div>'+html.escape(str(text))+'</div>','textCss':css,'pageSize':'custom','width':rect.width*25.4/72,'height':max(26,rect.height*4)*25.4/72,'margin':0,'pageNumbers':False,'allowRemoteAssets':False,'consent':False}
    root=Path(__file__).resolve().parents[1]
    with tempfile.TemporaryDirectory() as td:
        target=Path(td)/'text.pdf'
        result=subprocess.run(['node',str(root/'scripts/render_text.mjs')],input=__import__('json').dumps({'options':opts,'out':str(target)}),capture_output=True,text=True,timeout=45,cwd=root)
        if result.returncode or not target.exists():raise UserError('Unicode text rendering failed. Check Chromium installation.')
        with fitz.open(target) as src:
            blocks=src[0].get_text('blocks');bottom=max([b[3] for b in blocks],default=size*1.3)
            source_rect=fitz.Rect(0,0,src[0].rect.width,min(bottom+2,src[0].rect.height))
            scale=min(1,rect.height/max(1,source_rect.height))
            dest=fitz.Rect(rect.x0,rect.y0,rect.x0+source_rect.width*scale,rect.y0+source_rect.height*scale)
            page.show_pdf_page(dest,src,0,overlay=True)
            return scale

def font_name(name):
    return {'helvetica':'helv','times':'tiro','courier':'cour','serif':'tiro','sans-serif':'helv','monospace':'cour'}.get(str(name).lower(),'helv')

def fit_font(text, font, max_width, desired):
    size=max(4,min(float(desired),200))
    while size>4 and fitz.get_text_length(text,fontname=font,fontsize=size)>max_width: size-=0.5
    return size

def image_pdf(path, out, pagesize=None):
    img=fitz.open(path)
    pdf=fitz.open()
    pdfbytes=img.convert_to_pdf()
    src=fitz.open('pdf',pdfbytes)
    for source in src:
        rect=source.rect
        if pagesize:
            page=pdf.new_page(width=pagesize[0],height=pagesize[1])
            scale=min(pagesize[0]/rect.width,pagesize[1]/rect.height)
            w,h=rect.width*scale,rect.height*scale
            target=fitz.Rect((pagesize[0]-w)/2,(pagesize[1]-h)/2,(pagesize[0]+w)/2,(pagesize[1]+h)/2)
        else:
            page=pdf.new_page(width=rect.width,height=rect.height); target=page.rect
        page.show_pdf_page(target,src,source.number)
    pdf.save(out,garbage=4,deflate=True)
    pdf.close();src.close();img.close()
